content=json.loads((ROOT/'data/content.json').read_text())
new_ids={r[1] for r in ROWS}
content['tasks']=[q for q in content['tasks'] if q['id'] not in new_ids]
for q in content['tasks']:
    if q['id'] in ['paper','ramp','shadow','plant']: q['coach_only']=True
new=[]
for level,id,title,conditions,outcomes,frames,setup,variable,constants in ROWS:
    q={'id':id,'model_kind':'story','scene_key':id,'audio_key':id,'catalog_level':level,'title':title,'question':P('نغيّر شيئًا واحدًا. ماذا تلاحظ؟','We change one thing. What do you notice?'),'changed_variable':variable,'held_constants':constants,'conditions':conditions,'outcomes':[{'id':str(i),'label':v} for i,v in enumerate(outcomes+[P('لم يتضح لي','I am not sure')])],'setup':setup,'model_rule':P('مشاهد توضيحية مصممة للمقارنة، وليست قياسات أو برهانًا على نتيجة الواقع. غيّر العامل المحدد فقط عند التجربة مع المربي.','Designed scenes for comparison, not measurements or proof of real results. Change only the specified factor when testing with an adult.'),'model_values':[[0,0]] if id=='compare-magnet-paper' else [[0,1]],'asset_ids':[],'unit':P('ملاحظة','observation'),'seed_ref':'level'+str(level)+'-'+id,'frames':frames,'observe_prompts':[P('ماذا لاحظت في حالة '+c['ar']+'؟','What did you notice with '+c['en'].lower()+'?') for c in conditions]}
    new.append(q)
content['tasks']+=new
for level in content['levels']:level['available']=True
(ROOT/'data/content.json').write_text(json.dumps(content,ensure_ascii=False,indent=2)+'\n')
(ROOT/'data/content.js').write_text('window.WONDER_CONTENT='+json.dumps(content,ensure_ascii=False,separators=(',',':'))+';\n')
manifest=json.loads((ROOT/'data/audio-manifest.json').read_text());by_path={r['path']:r for r in manifest['items']}
for q in new:
    values={f:q[f] for f in ['question','setup','model_rule','changed_variable','held_constants']}
    values.update({'condition-'+str(i):v for i,v in enumerate(q['conditions'])});values.update({'outcome-'+str(i):v['label'] for i,v in enumerate(q['outcomes'])});values.update({'frame-'+str(i):v for i,v in enumerate(q['frames'])});values.update({'observe-'+str(i):v for i,v in enumerate(q['observe_prompts'])})
    for field,v in values.items():
        for lang in ['ar','en']:
            p='audio/'+lang+'-'+q['audio_key']+'-'+field+'.mp3';by_path[p]={'language':lang,'text':v[lang],'path':p}
manifest['items']=list(by_path.values());(ROOT/'data/audio-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
(ROOT/'data/levels-2-3-authored.json').write_text(json.dumps({'date':'2026-10-04','level_counts':{'2':20,'3':20},'activities':new},ensure_ascii=False,indent=2)+'\n')
assert len(new)==40 and all(sum(q['catalog_level']==l and not q.get('coach_only') for q in content['tasks'])==20 for l in [1,2,3])
print('Prepared 60 child activities, retained 4 coach activities and',len(manifest['items']),'audio references')
